// EJEMPLO FE V2 (29-oct-2026): oración "Si anoche no pudiste dormir pensando en lo que debes".
// Ilustración en movimiento que transmite paz: noche -> amanecer, una sola luz cálida, tres profundidades,
// movimiento lento y continuo. Los subtítulos, la voz, la música y el acabado los pone render_fe.py.
import React from 'react';
import {AbsoluteFill, Easing, interpolate} from 'remotion';
import {useS, en, clamp, DUR} from './kit';

const W = 1080;
const H = 1920;

// Momentos atados a la voz
const NOCHE = en('anoche');
const PESO = en('peso');
const CUENTAS = en('cuentas');
const ENTREGO = en('entrego');
const ANSIEDAD = en('ansiedad');
const PAZ = en('paz');
const CAMINOS = en('caminos');
const CONMIGO = en('conmigo');
const AMEN = en('amén');

const mezcla = (a: number[], b: number[], k: number) => `rgb(${a.map((x, i) => Math.round(x + (b[i] - x) * k)).join(',')})`;

const Cielo: React.FC<{amanecer: number}> = ({amanecer}) => {
  const arriba = mezcla([10, 16, 40], [72, 110, 170], amanecer);
  const medio = mezcla([22, 30, 66], [236, 170, 120], amanecer);
  const abajo = mezcla([30, 34, 70], [255, 214, 150], amanecer);
  return <AbsoluteFill style={{background: `linear-gradient(180deg, ${arriba} 0%, ${medio} 62%, ${abajo} 100%)`}} />;
};

const Estrellas: React.FC<{s: number; visibles: number}> = ({s, visibles}) => (
  <AbsoluteFill style={{opacity: visibles}}>
    {Array.from({length: 70}).map((_, i) => {
      const x = (i * 157) % W;
      const y = (i * 263) % 1050;
      const r = 1.5 + (i % 3);
      const brillo = 0.45 + 0.55 * Math.abs(Math.sin(s * 0.8 + i));
      return <div key={i} style={{position: 'absolute', left: x, top: y, width: r * 2, height: r * 2, borderRadius: r, background: '#fff8e0', opacity: brillo, boxShadow: '0 0 8px #fff3c4'}} />;
    })}
  </AbsoluteFill>
);

const Sol: React.FC<{amanecer: number; s: number}> = ({amanecer, s}) => {
  const y = interpolate(amanecer, [0, 1], [1500, 880], clamp);
  const r = 150 + Math.sin(s * 1.2) * 4;
  return (
    <div style={{position: 'absolute', left: W / 2 - r * 3, top: y - r * 3, width: r * 6, height: r * 6, opacity: amanecer}}>
      <div style={{position: 'absolute', inset: 0, borderRadius: '50%', background: 'radial-gradient(circle, rgba(255,226,160,0.55) 0%, rgba(255,190,120,0.18) 35%, transparent 70%)'}} />
      <div style={{position: 'absolute', left: r * 2, top: r * 2, width: r * 2, height: r * 2, borderRadius: '50%', background: 'radial-gradient(circle at 40% 35%, #fffbe8 0%, #ffd98a 55%, #f3a95c 100%)', boxShadow: '0 0 120px 40px rgba(255,210,140,0.45)'}} />
    </div>
  );
};

const Rayos: React.FC<{fuerza: number; s: number}> = ({fuerza, s}) => (
  <AbsoluteFill style={{opacity: fuerza * 0.55, mixBlendMode: 'screen'}}>
    {Array.from({length: 9}).map((_, i) => {
      const ang = -40 + i * 10 + Math.sin(s * 0.3 + i) * 2;
      return <div key={i} style={{position: 'absolute', left: W / 2 - 40, top: 880, width: 80, height: 1700, transformOrigin: '50% 0%', transform: `rotate(${ang + 180}deg)`, background: 'linear-gradient(180deg, rgba(255,236,190,0.55), transparent 80%)', filter: 'blur(14px)'}} />;
    })}
  </AbsoluteFill>
);

// Colinas con volumen: degradado de la luz (centro) hacia la sombra (bordes) y borde de luz arriba.
const Colina: React.FC<{y: number; alto: number; color: [string, string]; deriva: number; borde: number}> = ({y, alto, color, deriva, borde}) => (
  <svg width={W + 200} height={alto} style={{position: 'absolute', left: -100 + deriva, top: y}} viewBox={`0 0 ${W + 200} ${alto}`}>
    <defs>
      <linearGradient id={`c${y}`} x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stopColor={color[0]} />
        <stop offset="100%" stopColor={color[1]} />
      </linearGradient>
    </defs>
    <path d={`M0 ${alto * 0.45} C ${W * 0.25} ${alto * 0.1}, ${W * 0.45} ${alto * 0.5}, ${W * 0.65} ${alto * 0.25} S ${W + 120} ${alto * 0.2}, ${W + 200} ${alto * 0.35} L ${W + 200} ${alto} L 0 ${alto} Z`} fill={`url(#c${y})`} />
    <path d={`M0 ${alto * 0.45} C ${W * 0.25} ${alto * 0.1}, ${W * 0.45} ${alto * 0.5}, ${W * 0.65} ${alto * 0.25} S ${W + 120} ${alto * 0.2}, ${W + 200} ${alto * 0.35}`} fill="none" stroke="rgba(255,226,170,0.8)" strokeWidth={4} opacity={borde} />
  </svg>
);

const Casa: React.FC<{luz: number}> = ({luz}) => (
  <div style={{position: 'absolute', left: 640, top: 1180, width: 180, height: 150}}>
    <div style={{position: 'absolute', left: 0, top: 50, width: 180, height: 100, background: 'linear-gradient(90deg, #1a1d36, #10122a)', borderRadius: 6}} />
    <div style={{position: 'absolute', left: -12, top: 0, width: 0, height: 0, borderLeft: '102px solid transparent', borderRight: '102px solid transparent', borderBottom: '56px solid #14162e'}} />
    <div style={{position: 'absolute', left: 70, top: 78, width: 40, height: 44, background: '#ffd48a', borderRadius: 4, opacity: luz, boxShadow: `0 0 ${40 * luz}px ${16 * luz}px rgba(255,200,120,0.6)`}} />
  </div>
);

// Papeles (las cuentas) que suben y se vuelven pájaros de luz en "entrego"
const Papeles: React.FC<{s: number}> = ({s}) => (
  <AbsoluteFill>
    {Array.from({length: 7}).map((_, i) => {
      const t0 = CUENTAS + i * 0.18;
      const aparece = interpolate(s, [t0, t0 + 0.5], [0, 1], clamp);
      const sube = interpolate(s, [ENTREGO, ENTREGO + 4], [0, 1], {...clamp, easing: Easing.inOut(Easing.cubic)});
      const x = 300 + ((i * 97) % 480) + Math.sin(s * 1.3 + i) * 18 + sube * (i % 2 ? 160 : -160);
      const y = 1250 - aparece * (90 + (i % 3) * 40) - sube * 900;
      const ave = interpolate(s, [ENTREGO + 1, ENTREGO + 2], [0, 1], clamp);
      const aleteo = Math.sin(s * 9 + i) * 26;
      return (
        <div key={i} style={{position: 'absolute', left: x, top: y, opacity: aparece * (1 - interpolate(s, [ANSIEDAD + 2, ANSIEDAD + 3], [0, 1], clamp))}}>
          <div style={{position: 'absolute', width: 54, height: 68, background: 'linear-gradient(135deg, #f4efe2, #c9c2b0)', borderRadius: 4, transform: `rotate(${(i % 3 - 1) * 14 + Math.sin(s + i) * 6}deg)`, opacity: 1 - ave, boxShadow: '0 6px 14px rgba(0,0,0,0.35)'}} />
          <svg width={90} height={50} style={{position: 'absolute', left: -18, top: 6, opacity: ave}} viewBox="0 0 90 50">
            <path d={`M5 ${25 + aleteo / 2} Q 25 ${10 - aleteo / 3} 45 25 Q 65 ${10 - aleteo / 3} 85 ${25 + aleteo / 2}`} stroke="#fff2c8" strokeWidth={6} fill="none" strokeLinecap="round" style={{filter: 'drop-shadow(0 0 8px #ffd98a)'}} />
          </svg>
        </div>
      );
    })}
  </AbsoluteFill>
);

const Nubes: React.FC<{s: number}> = ({s}) => {
  const se_van = interpolate(s, [ANSIEDAD, ANSIEDAD + 3], [0, 1], {...clamp, easing: Easing.out(Easing.cubic)});
  return (
    <AbsoluteFill style={{opacity: (1 - se_van) * interpolate(s, [PESO, PESO + 1], [0, 0.85], clamp)}}>
      {[0, 1, 2, 3].map((i) => (
        <div key={i} style={{position: 'absolute', left: -200 + i * 320 + se_van * (i % 2 ? 500 : -500), top: 300 + (i % 2) * 160, width: 520, height: 200, borderRadius: 200, background: 'radial-gradient(ellipse at 50% 40%, #4a4e70, #2a2c48 70%)', filter: 'blur(10px)'}} />
      ))}
    </AbsoluteFill>
  );
};

const Camino: React.FC<{s: number}> = ({s}) => {
  const k = interpolate(s, [CAMINOS - 0.2, CAMINOS + 2.5], [0, 1], {...clamp, easing: Easing.inOut(Easing.quad)});
  return (
    <svg width={W} height={700} style={{position: 'absolute', left: 0, top: 1220}} viewBox={`0 0 ${W} 700`}>
      <defs>
        <linearGradient id="cam" x1="0" y1="1" x2="0" y2="0">
          <stop offset="0%" stopColor="#f6d9a2" />
          <stop offset="100%" stopColor="#fff4d6" />
        </linearGradient>
      </defs>
      <path d="M380 700 C 470 520, 600 420, 540 300 S 560 120, 540 40 L 560 40 C 590 130, 600 210, 600 300 S 560 520, 700 700 Z" fill="url(#cam)" opacity={0.85} style={{clipPath: `inset(${(1 - k) * 100}% 0 0 0)`}} />
    </svg>
  );
};

const Figura: React.FC<{s: number; abrazo: number}> = ({s, abrazo}) => {
  const respira = Math.sin(s * 1.4) * 3;
  return (
    <div style={{position: 'absolute', left: 470, top: 1400 + respira}}>
      <div style={{position: 'absolute', left: -120, top: -140, width: 380, height: 380, borderRadius: '50%', background: 'radial-gradient(circle, rgba(255,226,160,0.6), transparent 70%)', opacity: abrazo}} />
      <svg width={140} height={300} viewBox="0 0 140 300">
        <ellipse cx={70} cy={292} rx={50} ry={8} fill="rgba(0,0,0,0.35)" />
        <circle cx={70} cy={48} r={34} fill="#191a30" />
        <path d="M22 140 Q 70 80 118 140 L 128 288 L 12 288 Z" fill="#191a30" />
      </svg>
    </div>
  );
};

const Particulas: React.FC<{s: number; calida: number}> = ({s, calida}) => (
  <AbsoluteFill>
    {Array.from({length: 40}).map((_, i) => {
      const x = (i * 131) % W + Math.sin(s * 0.5 + i) * 30;
      const y = H - ((i * 211 + s * (18 + (i % 5) * 6)) % (H + 100));
      const r = 3 + (i % 4);
      return <div key={i} style={{position: 'absolute', left: x, top: y, width: r, height: r, borderRadius: r, background: calida > 0.5 ? '#ffe3a6' : '#dfe6ff', opacity: 0.35 + 0.3 * Math.sin(s + i), filter: 'blur(1px)'}} />;
    })}
  </AbsoluteFill>
);

export const Escena: React.FC = () => {
  const {s} = useS();
  const amanecer = interpolate(s, [PAZ - 0.3, PAZ + 4], [0, 1], {...clamp, easing: Easing.inOut(Easing.cubic)});
  const zoom = 1.08 - 0.06 * (s / Math.max(DUR, 1)) + 0.03 * interpolate(s, [CONMIGO, CONMIGO + 2], [0, 1], clamp);
  const deriva = Math.sin(s * 0.15) * 20;
  const abrazo = interpolate(s, [CONMIGO - 0.1, CONMIGO + 1.5], [0, 1], clamp);
  const final = interpolate(s, [AMEN, AMEN + 2], [0, 1], clamp);
  return (
    <AbsoluteFill style={{overflow: 'hidden', backgroundColor: '#0a0f24'}}>
      <AbsoluteFill style={{transform: `scale(${zoom}) translateX(${deriva}px)`, transformOrigin: '50% 60%'}}>
        <Cielo amanecer={amanecer} />
        <Estrellas s={s} visibles={1 - amanecer} />
        <Sol amanecer={amanecer} s={s} />
        <Rayos fuerza={amanecer + final * 0.3} s={s} />
        <Nubes s={s} />
        <Colina y={1000} alto={520} color={amanecer > 0.5 ? ['#7a6a8e', '#4a3e62'] : ['#2a2f55', '#171a36']} deriva={deriva * 0.3} borde={amanecer} />
        <Casa luz={interpolate(s, [NOCHE, NOCHE + 0.6], [0.3, 1], clamp) * (1 - amanecer * 0.6)} />
        <Colina y={1160} alto={760} color={amanecer > 0.5 ? ['#5e5a7a', '#2c2840'] : ['#1d2244', '#0e1028']} deriva={deriva * 0.6} borde={amanecer * 0.8} />
        <Camino s={s} />
        <Figura s={s} abrazo={abrazo} />
        <Papeles s={s} />
        <Particulas s={s} calida={amanecer} />
      </AbsoluteFill>
      <AbsoluteFill style={{background: 'radial-gradient(circle at 50% 55%, transparent 55%, rgba(5,6,20,0.55) 100%)'}} />
    </AbsoluteFill>
  );
};
